function errorMessage(error: unknown): string {
  if (error instanceof Error && error.message) return error.message.replace(/^User rejected the request\.?$/i, 'Wallet request was cancelled.');
  return 'The network request failed. Check your wallet and try again.';
}
function parseAmount(value: string): bigint { return parseNativeUsdc(value); }
function dateInput(offsetHours: number): string {
  const date = new Date(Date.now() + offsetHours * 60 * 60 * 1000);
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60_000);
  return local.toISOString().slice(0, 16);
}
function money(value: bigint | string | number): string {
  const [whole, fraction = ''] = formatUsdc(value, 6).split('.');
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `$${grouped}.${fraction.padEnd(2, '0')}`;
}
function formatInputAmount(value: string): string {
  const normalized = value.replaceAll(',', '').trim();
  if (!normalized) return '';
  const [whole, fraction] = normalized.split('.');
  const grouped = whole.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return fraction === undefined ? `${grouped}.00` : `${grouped}.${fraction}`;
}
function useScrollPhase(ref: { current: HTMLElement | null }): number {
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    let frame = 0;
    const update = () => {
      const node = ref.current;
      if (!node) return;
      const travel = Math.max(1, node.offsetHeight - window.innerHeight);
      setProgress(Math.max(0, Math.min(1, -node.getBoundingClientRect().top / travel)));
    };
    const onScroll = () => { window.cancelAnimationFrame(frame); frame = window.requestAnimationFrame(update); };
    update();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => { window.cancelAnimationFrame(frame); window.removeEventListener('scroll', onScroll); window.removeEventListener('resize', onScroll); };
  }, [ref]);
  return progress;
}
function hashReference(value: string): `0x${string}` {
  const text = value.trim();
  return isHex(text) && text.length === 66 ? text as `0x${string}` : keccak256(toBytes(text || 'CargoCommit commitment'));
}
function viewFromHash(hash: string): View {
  const route = hash.replace(/^#/, '').split('/')[0];
  if (route === 'orders' || route === 'order') return 'orders';
  if (route === 'create-order' || route === 'create') return 'create';
  if (route === 'proof') return 'proof';
  return 'home';
}
function orderFromHash(hash: string): Address | undefined {
  const value = hash.replace(/^#(?:orders?|order)\/?/, '').split('/')[0];
  return isAddress(value) ? value : undefined;
}
function dateLabel(value: string | bigint): string {
  const date = typeof value === 'bigint' ? new Date(Number(value) * 1000) : new Date(value);
  if (Number.isNaN(date.getTime())) return '—';
  return new Intl.DateTimeFormat(undefined, { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }).format(date).toUpperCase();
}
function partyState(value: string, account?: Address): 'empty' | 'valid' | 'invalid' | 'duplicate' {
  if (!value) return 'empty';
  if (!isAddress(value)) return 'invalid';
  if (account && value.toLowerCase() === account.toLowerCase()) return 'duplicate';
  return 'valid';
}
function addressSeed(value: string): number {
  return value.split('').reduce((sum, character) => sum + character.charCodeAt(0), 0);
}
function nextActionFor(role: Role, snapshot?: Snapshot): string {
  if (!snapshot) return 'READING STATE';
  const now = BigInt(Math.floor(Date.now() / 1000));
  if (snapshot.status === 5) return 'SETTLED';
  if (snapshot.status === 0) return role === 'supplier' ? 'ACCEPT ORDER' : role === 'buyer' ? 'WAITING FOR ACCEPTANCE' : 'SUPPLIER ACCEPTS';
  if (snapshot.status === 1) return role === 'buyer' ? 'FUND ORDER' : role === 'supplier' ? 'WAITING FOR FUNDING' : 'BUYER FUNDS';
  if (snapshot.status === 2) return role === 'supplier' ? 'SUBMIT EVIDENCE' : role === 'buyer' && now > snapshot.shipmentDeadline ? 'CLAIM REFUND' : 'SHIPMENT EVIDENCE';
  if (snapshot.status === 3) {
    if (role === 'buyer') return now <= snapshot.buyerDecisionDeadline ? 'APPROVE OR DISPUTE' : 'SUPPLIER TIMEOUT';
    if (role === 'supplier') return now > snapshot.buyerDecisionDeadline ? 'CLAIM TIMEOUT' : 'WAITING FOR BUYER';
    return 'BUYER APPROVES OR DISPUTES';
  }
  if (snapshot.status === 4) {
    if (role === 'arbiter' && now <= snapshot.disputeDeadline) return 'RESOLVE DISPUTE';
    if (now > snapshot.disputeDeadline) return 'CLAIM FALLBACK';
    return 'DISPUTE WINDOW OPEN';
  }
  return statusLabel(snapshot.status).toUpperCase();
}

