function reviewDateLabel(value: bigint): string {
  const date = new Date(Number(value) * 1000);
  if (Number.isNaN(date.getTime())) return '—';
  return new Intl.DateTimeFormat(undefined, { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date).toUpperCase();
}

function walletReviewMessage(check: ReturnType<typeof checkReviewedBuyer>): string {
  if (check.reason !== 'changed') return 'Review the order again before signing.';
  return `WALLET CHANGED\nBuyer changed from ${check.reviewedBuyer ?? 'NOT SET'} to ${check.activeBuyer ?? 'NOT CONNECTED'}.\nReview this order again before signing.`;
}

function ReviewArgumentSummary({ review, poReference }: { review: CreateOrderReview; poReference: string }) {
  const [fundingDeadline, shipmentDeadline, buyerDecisionDeadline, disputeDeadline] = review.deadlines;
  const buyer = review.buyer && isAddress(review.buyer) ? review.buyer : 'NOT SET';
  return <div className="review-argument-summary"><div className="review-argument-heading"><span>CREATE ORDER ARGUMENTS</span><small>CONFIRM BEFORE WALLET SIGNATURE</small></div><div className="review-argument-grid"><div><span>BUYER / CONNECTED WALLET</span><strong>{buyer}</strong></div><div><span>SUPPLIER / EXPORTER</span><strong>{isAddress(review.supplier) ? review.supplier : 'NOT SET'}</strong></div><div><span>ARBITER</span><strong>{isAddress(review.arbiter) ? review.arbiter : 'NOT SET'}</strong></div><div><span>ORDER AMOUNT</span><strong>{money(review.amount)}</strong></div><div><span>DEPOSIT</span><strong>{review.depositPercent}% / RELEASED</strong></div><div><span>FALLBACK SETTLEMENT</span><strong>SUPPLIER {review.fallbackPercent}% · BUYER {100 - review.fallbackPercent}%</strong></div><div><span>FUNDING BY</span><strong>{reviewDateLabel(fundingDeadline)}</strong></div><div><span>SHIPMENT BY</span><strong>{reviewDateLabel(shipmentDeadline)}</strong></div><div><span>BUYER DECISION BY</span><strong>{reviewDateLabel(buyerDecisionDeadline)}</strong></div><div><span>DISPUTE DEADLINE</span><strong>{reviewDateLabel(disputeDeadline)}</strong></div></div><div className="review-transaction-meta"><div><span>NETWORK</span><strong>ARC MAINNET / 5042</strong></div><div><span>FACTORY</span><strong>{FACTORY_ADDRESS}</strong></div><div><span>CREATE TRANSACTION VALUE</span><strong>0 USDC <small>(PRINCIPAL FUNDED LATER)</small></strong></div><div><span>LOCAL PO REFERENCE</span><strong>{poReference || 'NOT SET'} <small>LOCAL-ONLY METADATA</small></strong></div><div><span>ONCHAIN TERMS COMMITMENT</span><strong>DERIVED FROM IMMUTABLE TERMS AFTER CREATION</strong></div></div></div>;
}

function SettlementSheet({ total, deposit, reserve, depositPercent, reservePercent, fallbackBps, supplier, arbiter, fundingDeadline, shipmentDeadline, documentCommitment, ready, missing, stage }: { total: bigint; deposit: bigint; reserve: bigint; depositPercent: number; reservePercent: number; fallbackBps: string; supplier: string; arbiter: string; fundingDeadline: string; shipmentDeadline: string; documentCommitment: string; ready: boolean; missing: string[]; stage: TransactionStage }) {
  const stageLabel = stage === 'success' ? 'ORDER CREATED' : stage === 'confirming' ? 'CONFIRMING' : stage === 'signing' ? 'AWAITING SIGNATURE' : ready ? 'READY TO CREATE' : 'DRAFT';
  return <aside className="settlement-sheet live-instrument-sheet"><div className="sheet-top"><span>LIVE SETTLEMENT INSTRUMENT</span><span>ARC / 5042</span></div><div className="sheet-big-number"><span>TOTAL / {depositPercent}—{reservePercent} SPLIT</span><strong>{money(total)}</strong><small>NATIVE USDC · {dateLabel(fundingDeadline)} FUND BY</small></div><div className="settlement-sheet-lines"><div><span>RELEASE AT FUNDING / {depositPercent}%</span><strong>{money(deposit)}</strong></div><div><span>PROTECTED UNTIL SHIPMENT / {reservePercent}%</span><strong>{money(reserve)}</strong></div><div><span>IF DISPUTE WINDOW EXPIRES / SUPPLIER</span><strong>{fallbackBps || '—'}%</strong></div></div><div className="sheet-bar"><SettlementBar depositAmount={deposit} reserveAmount={reserve} depositPercent={depositPercent} /></div><div className="instrument-parties"><div><span>SUPPLIER</span><strong>{isAddress(supplier) ? shortenAddress(supplier) : 'NOT SET'}</strong></div><div><span>ARBITER</span><strong>{isAddress(arbiter) ? shortenAddress(arbiter) : 'NOT SET'}</strong></div></div><div className="instrument-deadlines"><div><span>FUND BY</span><b>{dateLabel(fundingDeadline)}</b></div><div><span>SHIP BY</span><b>{dateLabel(shipmentDeadline)}</b></div></div><div className="sheet-note"><DocumentStamp tone={ready ? 'signal' : 'ink'}>{stageLabel}</DocumentStamp><p>{ready ? 'READY TO CREATE ON ARC.' : `${missing.length} ${missing.length === 1 ? 'ITEM' : 'ITEMS'} REQUIRED: ${missing.join(' · ')}`}</p></div>{documentCommitment && <small className="instrument-local-note">LOCAL DOCUMENT REFERENCE / RETAINED ON THIS DEVICE</small>}</aside>;
}

export function LegacyCreateOrder({ account, walletClient, walletProvider, onCreated }: { account?: Address; walletClient?: WalletClient; walletProvider?: Eip1193Provider; onCreated: (order: Address, hash: Hash) => void }) {
  const [supplier, setSupplier] = useState(''); const [arbiter, setArbiter] = useState(''); const [amount, setAmount] = useState('10000'); const [amountFocused, setAmountFocused] = useState(false); const [depositBps, setDepositBps] = useState('30'); const [fallbackBps, setFallbackBps] = useState('50');
  const [fundingDeadline, setFundingDeadline] = useState(dateInput(24)); const [shipmentDeadline, setShipmentDeadline] = useState(dateInput(72)); const [decisionDeadline, setDecisionDeadline] = useState(dateInput(120)); const [disputeDeadline, setDisputeDeadline] = useState(dateInput(288)); const [poReference, setPoReference] = useState(''); const [documentCommitment, setDocumentCommitment] = useState(''); const [activePhase, setActivePhase] = useState(1); const [reviewedBuyer, setReviewedBuyer] = useState<Address>(); const [reviewInvalidated, setReviewInvalidated] = useState(false); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [stage, setStage] = useState<TransactionStage>('idle'); const [success, setSuccess] = useState<{ order: Address; hash: Hash }>();
  const total = useMemo(() => { try { return parseNativeUsdc(amount); } catch { return 0n; } }, [amount]); const split = useMemo(() => settlementSplit(total, Number(depositBps) || 0), [total, depositBps]); const { depositAmount: deposit, reserveAmount: reserve } = split;
  const partiesReady = distinctPartyAddresses(account, supplier, arbiter);
  const settlementReady = total > 0n && Number.isInteger(Number(depositBps)) && Number(depositBps) >= 1 && Number(depositBps) <= 99 && Number.isInteger(Number(fallbackBps)) && Number(fallbackBps) >= 0 && Number(fallbackBps) <= 100;
  const deadlines = useMemo(() => [fundingDeadline, shipmentDeadline, decisionDeadline, disputeDeadline].map(parseDeadlineSeconds) as [bigint, bigint, bigint, bigint], [fundingDeadline, shipmentDeadline, decisionDeadline, disputeDeadline]);
  const review = buildCreateOrderReview({ buyer: account, supplier, arbiter, amount: total, depositPercent: Number(depositBps) || 0, fallbackPercent: Number(fallbackBps) || 0, deadlines });
  const deadlinesReady = deadlines[0] > BigInt(Math.floor(Date.now() / 1000)) && deadlines[1] > deadlines[0] && deadlines[2] > deadlines[1] && deadlines[3] > deadlines[2];
  const commitmentReady = Boolean(poReference.trim() && documentCommitment.trim());
  const missing = [!account ? 'Connected buyer' : '', !partiesReady ? 'Supplier and arbiter' : '', !settlementReady ? 'Amount and split' : '', !deadlinesReady ? 'Chronological deadlines' : '', !commitmentReady ? 'PO reference and local document reference' : ''].filter(Boolean);
  const draftReady = missing.length === 0;
  const reviewState = deriveCreateReviewState({ draftReady, reviewedBuyer, activeBuyer: account, reviewInvalidated });
  const reviewChanged = reviewState.changed;
  const reviewReady = reviewState.reviewReady;
  const reviewBlocked = reviewState.createBlocked;
  const ready = reviewReady;
  const phases = [
    ['01', 'PARTIES', partiesReady], ['02', 'SETTLEMENT', settlementReady], ['03', 'DELIVERY', deadlinesReady], ['04', 'COMMITMENT', commitmentReady], ['05', 'REVIEW', reviewReady],
  ] as const;
 const jumpToPhase = (index: number) => { if (index === 5) { setReviewedBuyer(account); setReviewInvalidated(false); setError(''); } else { setReviewedBuyer(undefined); setReviewInvalidated(false); } setActivePhase(index); window.setTimeout(() => document.getElementById(`composer-phase-${index}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 0); };
  useEffect(() => { if (reviewChanged) setError(walletReviewMessage({ ok: false, reason: 'changed', reviewedBuyer, activeBuyer: account })); }, [account, reviewChanged, reviewedBuyer]);
  const validate = () => validateCreateDraft({ account, supplier, arbiter, total, depositPercent: depositBps, fallbackPercent: fallbackBps, deadlines, now: BigInt(Math.floor(Date.now() / 1000)), poReference, documentReference: documentCommitment, walletAvailable: Boolean(walletClient) });
  const create = async (event: React.FormEvent) => { event.preventDefault(); setError(''); setMessage(''); const validation = validate(); if (validation) { setError(validation); return; } if (!account || !walletClient || !walletProvider) return; const initialReview = checkReviewedBuyer(reviewedBuyer, account); if (reviewBlocked || !initialReview.ok) { setReviewInvalidated(true); setError(walletReviewMessage(initialReview)); return; } let activeWallet: Awaited<ReturnType<typeof syncArcWallet>>; try { activeWallet = await syncArcWallet(walletProvider); } catch (e) { setError(errorMessage(e)); return; } const signerCheck = checkReviewedBuyer(reviewedBuyer, activeWallet?.account); if (!activeWallet || !walletProviderMatches(walletProvider, activeWallet.provider) || !signerCheck.ok) { setReviewInvalidated(true); setError(walletReviewMessage(signerCheck)); return; } setBusy(true); setStage('preparing'); try { setStage('signing'); const createCall = buildCreateOrderCall({ buyer: activeWallet.account, supplier: supplier as Address, arbiter: arbiter as Address, amount: total, depositPercent: Number(depositBps), fallbackPercent: Number(fallbackBps), deadlines }); const hash = await activeWallet.walletClient.writeContract({ address: FACTORY_ADDRESS, abi: factoryAbi, functionName: 'createOrder', args: createCall.args, value: createCall.value, chain: arcMainnet, account: activeWallet.account } as never); setStage('submitted'); setMessage(`Submitted to Arc · ${shortenAddress(hash)}`); setStage('confirming'); const receipt = await publicClient.waitForTransactionReceipt({ hash }); if (receipt.status !== 'success') throw new Error('The order creation transaction reverted.'); const logs = await fetchOrderCreatedLogs(publicClient, { fromBlock: receipt.blockNumber, toBlock: receipt.blockNumber }); const created = logs.find((log) => log.transactionHash?.toLowerCase() === hash.toLowerCase()); if (!created) throw new Error('Receipt succeeded, but the OrderCreated event could not be read back.'); localStorage.setItem(`cargocommit:order:${created.order}`, JSON.stringify({ poReference: poReference.trim(), documentCommitment: documentCommitment.trim(), savedAt: new Date().toISOString() })); setSuccess({ order: created.order, hash }); setStage('success'); setMessage('Purchase order created. Its terms are now immutable.'); } catch (e) { setStage('idle'); setError(errorMessage(e)); } finally { setBusy(false); } };
  const statusMessage = stage === 'preparing' ? 'PREPARING ORDER' : stage === 'signing' ? 'AWAITING WALLET SIGNATURE' : stage === 'submitted' ? 'SUBMITTED TO ARC' : stage === 'confirming' ? 'CONFIRMING' : stage === 'success' ? 'ORDER CREATED' : '';
  return <main className="page-shell page-content-v2 create-page-v2"><div className="document-heading"><div><SectionMark index="NEW TRADE ORDER" label="COMMERCIAL DOCUMENT" /><h1>SD / PO / 2026 / <span>0043</span></h1></div><div className="document-heading-meta"><span>FACTORY</span><a href={explorerAddress(FACTORY_ADDRESS)} target="_blank" rel="noreferrer">{shortenAddress(FACTORY_ADDRESS, 10, 8)} ↗</a><span>NETWORK / ARC 5042</span></div></div><div className="composer-progress" aria-label="Order composer progress">{phases.map(([number, label, complete], index) => <button type="button" className={`${activePhase === index + 1 ? 'active ' : ''}${complete ? 'complete' : ''}`} onClick={() => jumpToPhase(index + 1)} key={number}><span>{number}</span><strong>{label}</strong><i aria-hidden="true" /></button>)}</div><div className="create-document-layout composer-layout"><form className="trade-form-v2 composer-form" onSubmit={create}><section id="composer-phase-1" className={`composer-phase ${activePhase === 1 ? 'active' : ''}`}><div className="form-block-label">01 / PARTIES</div><div className="party-composition"><div className="party-card buyer-card"><PartyGlyph address={account} /><span className="party-role">BUYER / IMPORTER</span><strong>{account ? shortenAddress(account) : 'Connect wallet'}</strong><small>Connected wallet / order originator</small><PartyStatus value={account ?? ''} account={undefined} label="BUYER" /></div><div className="funded-order-label"><span>FUNDED ORDER</span><i /></div><div className="party-card"><PartyGlyph address={supplier} /><span className="party-role">SUPPLIER / EXPORTER</span><input aria-label="Supplier wallet address" value={supplier} onChange={(e) => setSupplier(e.target.value.trim())} placeholder="0x supplier address" /><small>Receives the production release.</small><PartyStatus value={supplier} account={account} label="SUPPLIER" /></div><div className="party-card"><PartyGlyph address={arbiter} /><span className="party-role">ARBITER</span><input aria-label="Arbiter wallet address" value={arbiter} onChange={(e) => setArbiter(e.target.value.trim())} placeholder="0x arbiter address" /><small>Resolves only a disputed reserve.</small><PartyStatus value={arbiter} account={account} label="ARBITER" /></div></div></section><section id="composer-phase-2" className={`composer-phase ${activePhase === 2 ? 'active' : ''}`}><div className="form-block-label">02 / SETTLEMENT</div><div className="field-grid-v2"><Field label="Order amount"><div className="input-unit-v2"><input inputMode="decimal" value={amountFocused ? amount : formatInputAmount(amount)} onFocus={() => setAmountFocused(true)} onBlur={() => setAmountFocused(false)} onChange={(e) => setAmount(e.target.value.replaceAll(',', ''))} /><span>USDC</span></div></Field><Field label="Fallback supplier share if dispute expires"><div className="input-unit-v2"><input inputMode="numeric" min="0" max="100" value={fallbackBps} onChange={(e) => setFallbackBps(e.target.value.replace(/\D/g, '').slice(0, 3))} /><span>%</span></div></Field></div><div className="split-editor"><div className="split-editor-head"><span>RELEASE AT FUNDING</span><strong>{split.depositBps}%</strong><span>PROTECTED</span><strong>{split.reserveBps}%</strong></div><input aria-label="Production deposit percentage" type="range" min="1" max="99" value={Number(depositBps) || 1} onChange={(e) => setDepositBps(e.target.value)} /><div className="split-quick-choices">{['20', '30', '40', '50'].map((value) => <button type="button" className={depositBps === value ? 'active' : ''} onClick={() => setDepositBps(value)} key={value}>{value} / {100 - Number(value)}</button>)}</div><SettlementBar depositAmount={deposit} reserveAmount={reserve} depositPercent={split.depositBps} /></div><details className="fallback-explainer"><summary>How fallback settlement works</summary><p>If the dispute window expires without an arbiter resolution, the contract pays the supplier {fallbackBps}% of the remaining reserve and returns {100 - (Number(fallbackBps) || 0)}% to the buyer.</p></details></section><section id="composer-phase-3" className={`composer-phase ${activePhase === 3 ? 'active' : ''}`}><div className="form-block-label">03 / DELIVERY</div><div className="delivery-timeline"><div><span>NOW</span><i>│</i></div><div><span>FUND BY</span><b>{dateLabel(fundingDeadline)}</b><i>│</i></div><div><span>SHIP BY</span><b>{dateLabel(shipmentDeadline)}</b><i>│</i></div><div><span>FALLBACK / DISPUTE WINDOW</span><b>{dateLabel(disputeDeadline)}</b></div></div><div className="field-grid-v2"><Field label="Funding deadline"><input type="datetime-local" value={fundingDeadline} onChange={(e) => setFundingDeadline(e.target.value)} /></Field><Field label="Shipment deadline"><input type="datetime-local" value={shipmentDeadline} onChange={(e) => setShipmentDeadline(e.target.value)} /></Field><Field label="Buyer decision deadline"><input type="datetime-local" value={decisionDeadline} onChange={(e) => setDecisionDeadline(e.target.value)} /></Field><Field label="Dispute resolution deadline"><input type="datetime-local" value={disputeDeadline} onChange={(e) => setDisputeDeadline(e.target.value)} /></Field></div>{!deadlinesReady && <p className="inline-validation">Funding, shipment, buyer decision and dispute deadlines must move forward in that order.</p>}</section><section id="composer-phase-4" className={`composer-phase ${activePhase === 4 ? 'active' : ''}`}><div className="form-block-label">04 / COMMITMENT</div><div className="commitment-copy"><span>COMMERCIAL TERMS</span><p>Documents stay offchain. The arbitrary local reference below is not uploaded or anchored. The deployed factory derives the onchain <code>termsHash</code> from the immutable parties, amount, split and deadlines only.</p></div><Field label="Purchase order reference"><input value={poReference} onChange={(e) => setPoReference(e.target.value)} placeholder="PO-2048 / internal reference" /></Field><Field label="Local document reference"><input value={documentCommitment} onChange={(e) => setDocumentCommitment(e.target.value)} placeholder="Internal fingerprint or reference text" /><small className="field-hint-v2">Retained locally for this device; it is not passed to the factory ABI and does not affect the onchain termsHash.</small></Field></section><section id="composer-phase-5" className={`composer-phase review-phase ${activePhase === 5 ? 'active' : ''}`}><div className="form-block-label">05 / REVIEW PURCHASE ORDER</div><div className="review-document"><div className="review-document-top"><span>SD / PO / 2026 / 0043</span><DocumentStamp tone={ready ? 'signal' : 'ink'}>{ready ? 'READY TO CREATE' : 'DRAFT'}</DocumentStamp></div><div className="review-total"><span>TOTAL</span><strong>{money(total)}</strong></div><div className="review-grid"><div><span>RELEASE AT FUNDING / {split.depositBps}%</span><strong>{money(deposit)}</strong></div><div><span>PROTECTED / {split.reserveBps}%</span><strong>{money(reserve)}</strong></div><div><span>SUPPLIER</span><strong>{isAddress(supplier) ? shortenAddress(supplier) : 'NOT SET'}</strong></div><div><span>ARBITER</span><strong>{isAddress(arbiter) ? shortenAddress(arbiter) : 'NOT SET'}</strong></div><div><span>FUND BY</span><strong>{dateLabel(fundingDeadline)}</strong></div><div><span>SHIP BY</span><strong>{dateLabel(shipmentDeadline)}</strong></div><div><span>LOCAL PO REFERENCE</span><strong>{poReference || 'NOT SET'}</strong></div><div><span>ONCHAIN TERMS COMMITMENT</span><strong>DERIVED FROM IMMUTABLE TERMS</strong></div></div></div><ReviewArgumentSummary review={review} poReference={poReference} />{reviewChanged && <div className="form-alert-v2 error wallet-changed-alert"><strong>WALLET CHANGED</strong><span>Your active wallet changed from: {reviewedBuyer ?? 'NOT SET'}</span><span>to: {account ?? 'NOT CONNECTED'}</span><button type="button" className="quiet-button" onClick={() => jumpToPhase(5)}>Review updated order</button></div>}{error && <div className="form-alert-v2 error">{error}</div>}{message && <div className="form-alert-v2 success">{message}</div>}{statusMessage && <div className="transaction-rail"><StatusDot active={stage === 'success'} /><span>{statusMessage}</span></div>}{stage === 'success' && success ? <div className="creation-success"><DocumentStamp>PURCHASE ORDER CREATED</DocumentStamp><p>{success.order}</p><div><TxLink hash={success.hash}>View transaction {shortenAddress(success.hash)}</TxLink><a href={explorerAddress(success.order)} target="_blank" rel="noreferrer">View order ↗</a></div><button type="button" className="quiet-button" onClick={() => onCreated(success.order, success.hash)}>View order workspace</button><button type="button" className="secondary-button" onClick={() => { setSuccess(undefined); setStage('idle'); setMessage(''); setError(''); setActivePhase(1); }}>Create another</button></div> : <button type="submit" className="primary-button form-submit-v2" disabled={busy || !ready || reviewBlocked}>{busy ? statusMessage || 'Preparing order…' : 'Create order on Arc'}<span>↗</span></button>}</section></form><SettlementSheet total={total} deposit={deposit} reserve={reserve} depositPercent={split.depositBps} reservePercent={split.reserveBps} fallbackBps={fallbackBps} supplier={supplier} arbiter={arbiter} fundingDeadline={fundingDeadline} shipmentDeadline={shipmentDeadline} documentCommitment={documentCommitment} ready={ready} missing={missing} stage={stage} /></div></main>;
}

type OrderReadState = 'idle' | 'loading' | 'success' | 'error';

export function LegacyOrdersPage({ account, orders, selected, onSelect, onRefresh, onConnect, onCreate, loading, readState, readError }: { account?: Address; orders: EnrichedOrder[]; selected?: Address; onSelect: (order: Address) => void; onRefresh: () => void; onConnect: () => void; onCreate: () => void; loading: boolean; readState: OrderReadState; readError: string }) {
  const [filter, setFilter] = useState<OrderFilter>('all');
  const filtered = orders.filter((order) => { const snapshot = order.snapshot; if (filter === 'all') return true; if (!snapshot) return filter === 'active'; if (filter === 'settled') return snapshot.status === 5; if (filter === 'active') return snapshot.status !== 5; const action = nextActionFor(roleFor(account, snapshot.buyer, snapshot.supplier, snapshot.arbiter), snapshot); return ['ACCEPT ORDER', 'FUND ORDER', 'SUBMIT EVIDENCE', 'CLAIM REFUND', 'APPROVE OR DISPUTE', 'CLAIM TIMEOUT', 'RESOLVE DISPUTE', 'CLAIM FALLBACK'].includes(action); });
  const ledger = filtered.length === 0
    ? <EmptyState title="NO ORDERS FOUND" copy="The Arc order register returned successfully, but no orders involve this wallet." action="Create order" onAction={onCreate} />
    : <div className="ledger-list"><div className="ledger-heading"><span>REF / ORDER</span><span>ROLE</span><span>AMOUNT / SPLIT</span><span>STATE / NEXT ACTION</span><span>DEADLINE</span></div>{filtered.map((order, index) => { const snapshot = order.snapshot; const role = roleFor(account, snapshot?.buyer ?? order.buyer, snapshot?.supplier ?? order.supplier, snapshot?.arbiter ?? order.arbiter); const action = nextActionFor(role, snapshot); return <button className={`ledger-row ${selected === order.order ? 'selected' : ''}`} onClick={() => onSelect(order.order)} key={order.order}><span className="ledger-index">{String(index + 1).padStart(2, '0')}</span><span className="ledger-order"><strong>PO / {shortenAddress(order.order, 8, 6)}</strong><small>{shortenAddress(order.buyer)} BUYER · {shortenAddress(order.supplier)} SUPPLIER</small></span><span className="ledger-role"><b>{role.toUpperCase()}</b><small>{snapshot ? money(snapshot.orderAmount) : money(order.orderAmount)} · {snapshot ? snapshot.depositBps : order.depositBps}/{100 - (snapshot?.depositBps ?? order.depositBps)}</small></span><span className="ledger-state"><b>{snapshot ? statusLabel(snapshot.status).toUpperCase() : 'READING…'}</b><small>{action}</small></span><span className="ledger-deadline"><b>{snapshot ? dateLabel(snapshot.shipmentDeadline) : dateLabel(order.shipmentDeadline)}</b><small>{snapshot ? `${money(snapshot.reserveRemaining)} RESERVE` : 'READING STATE'}</small></span><em>↗</em></button>; })}</div>;
  const registerError = <div className="form-alert-v2 error order-read-alert"><span>ORDER REGISTER UNAVAILABLE · Arc could not be reached. {readError || 'Retry the order register.'}</span><button type="button" className="quiet-button" onClick={onRefresh}>Retry</button></div>;
  const registerContent = readState === 'error'
    ? orders.length > 0 ? <>{registerError}{ledger}</> : <EmptyState title="ORDER REGISTER UNAVAILABLE" stamp="READ ERROR" copy={`Arc could not be reached. ${readError || 'Retry the order register.'}`} action="Retry" onAction={onRefresh} />
    : readState !== 'success'
      ? <EmptyState title="READING ORDER REGISTER" stamp="READING" copy="Reading public OrderCreated events from Arc mainnet." />
      : ledger;
  return <main className="page-shell page-content-v2 orders-page-v2"><div className="orders-header-v2"><div><SectionMark index="TRADE LEDGER" label="DISCOVERED FROM ARC" /><h1>Order<br /><span>register.</span></h1></div><div><p>Live <code>OrderCreated</code> events involving the connected wallet. The chain is the index; no private order database is assumed.</p><button className="quiet-button" onClick={onRefresh} disabled={loading}>{loading ? 'Reading Arc…' : 'Refresh ledger ↻'}</button></div></div>{!account ? <EmptyState title="Connect to discover orders" copy="Seldra reads orders involving the connected Arc wallet." action="Connect wallet" onAction={onConnect} /> : <><div className="filter-row-v2">{(['all', 'active', 'awaiting', 'settled'] as const).map((item) => <button className={filter === item ? 'active' : ''} onClick={() => setFilter(item)} key={item}>{item === 'all' ? 'ALL' : item === 'active' ? 'ACTIVE' : item === 'awaiting' ? 'AWAITING ACTION' : 'SETTLED'}</button>)}</div>{registerContent}</>}</main>;
}
function EmptyState({ title, copy, action, onAction, stamp = 'NO RECORD' }: { title: string; copy: string; action?: string; onAction?: () => void; stamp?: string }) { return <div className="empty-state-v2"><DocumentStamp tone="ink">{stamp}</DocumentStamp><h2>{title}</h2><p>{copy}</p>{action && onAction && <button className="secondary-button empty-state-action" onClick={onAction}>{action}</button>}</div>; }

export function LegacyOrderDetail({ account, order, walletClient, onRefresh }: { account?: Address; order?: EnrichedOrder; walletClient?: WalletClient; onRefresh: () => void }) {
  const [snapshot, setSnapshot] = useState<Snapshot | undefined>(order?.snapshot); const [busy, setBusy] = useState(false); const [txHash, setTxHash] = useState<Hash>(); const [error, setError] = useState(''); const [evidence, setEvidence] = useState(''); const [reason, setReason] = useState(''); const [supplierPayout, setSupplierPayout] = useState('');
  const refresh = useCallback(async () => { if (!order) return; try { setSnapshot(await readOrderSnapshot(publicClient, order.order)); } catch (e) { setError(errorMessage(e)); } }, [order]);
  useEffect(() => { setSnapshot(order?.snapshot); setError(''); void refresh(); }, [order, refresh]); useEffect(() => { const timer = window.setInterval(() => void refresh(), 12_000); return () => window.clearInterval(timer); }, [refresh]);
  if (!order || !snapshot) return <aside className="order-detail-v2 empty-detail-v2"><SectionMark index="ORDER" label={error ? 'READ ERROR' : 'SELECT A RECORD'} /><h2>{error ? <>Order detail<br /><span>unavailable.</span></> : <>The order view<br /><span>is waiting.</span></>}</h2><p>{error ? `Arc could not be reached. ${error}` : 'Select an order from the ledger to inspect immutable terms, state, roles, and the next permitted action.'}</p>{error && <button type="button" className="secondary-button empty-state-action" onClick={() => void refresh()}>Retry</button>}</aside>;
  const role = roleFor(account, snapshot.buyer, snapshot.supplier, snapshot.arbiter); const now = BigInt(Math.floor(Date.now() / 1000)); const fundingExpired = now > snapshot.fundingDeadline; const shipmentExpired = now > snapshot.shipmentDeadline; const decisionExpired = now > snapshot.buyerDecisionDeadline; const disputeExpired = now > snapshot.disputeDeadline;
  const send = async (functionName: string, args: readonly unknown[] = [], value?: bigint) => { if (!account || !walletClient) return setError('Connect the wallet for this order role before continuing.'); setBusy(true); setError(''); setTxHash(undefined); try { const hash = await walletClient.writeContract({ address: order.order, abi: orderAbi, functionName, args, value, chain: arcMainnet, account } as never); setTxHash(hash); const receipt = await publicClient.waitForTransactionReceipt({ hash }); if (receipt.status !== 'success') throw new Error('The transaction reverted. No state was changed.'); await refresh(); onRefresh(); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } };
  const metadata = (() => { try { return JSON.parse(localStorage.getItem(`cargocommit:order:${order.order}`) ?? '{}') as { poReference?: string; documentCommitment?: string }; } catch { return {}; } })();
  const timeline = [['TERMS CREATED', snapshot.status >= 0], ['SUPPLIER ACCEPTED', snapshot.status >= 1], ['ORDER FUNDED', snapshot.status >= 2], ['EVIDENCE SUBMITTED', snapshot.status >= 3], [snapshot.status === 4 ? 'DISPUTE ACTIVE' : 'SETTLED / RESOLVED', snapshot.status >= 5 || snapshot.status === 4]] as const;
  const reserveTerms = snapshot.orderAmount - snapshot.depositAmount; const showAction = role !== 'observer' || (snapshot.status === 4 && disputeExpired);
  return <aside className="order-detail-v2"><div className="order-detail-top"><div><SectionMark index="ACTIVE ORDER" label={metadata.poReference || `SD / ${shortenAddress(order.order, 8, 6)}`} /><h2>{money(snapshot.orderAmount)} <small>USDC</small></h2></div><a href={explorerAddress(order.order)} target="_blank" rel="noreferrer">OPEN ORDER ↗</a></div><SettlementBar depositAmount={snapshot.depositAmount} reserveAmount={reserveTerms} reserveLabel={snapshot.status === 5 ? 'RELEASED' : 'PROTECTED'} /><div className="detail-state-line"><DocumentStamp tone={snapshot.status === 4 ? 'alert' : snapshot.status === 5 ? 'signal' : 'ink'}>{statusLabel(snapshot.status)}</DocumentStamp><span>{snapshot.status === 4 ? 'Normal release frozen' : snapshot.status === 5 ? outcomeLabel(snapshot.outcome) : 'Lifecycle in progress'}</span></div><div className="detail-accounting-v2"><div><span>TOTAL FUNDED</span><strong>{money(snapshot.orderAmount)}</strong></div><div><span>DEPOSIT / {snapshot.depositBps}%</span><strong>{money(snapshot.depositAmount)}</strong></div><div><span>RESERVE REMAINING</span><strong>{money(snapshot.reserveRemaining)}</strong></div><div><span>CONTRACT BALANCE</span><strong>{money(snapshot.contractBalance)}</strong></div></div><div className="detail-timeline-v2">{timeline.map(([label, done]) => <div key={label}><StatusDot active={done} /><span>{label}</span>{done && <b>✓</b>}</div>)}</div><div className="detail-terms-grid"><div><span>FUND BY</span><strong>{dateLabel(snapshot.fundingDeadline)}</strong></div><div><span>SHIP BY</span><strong>{dateLabel(snapshot.shipmentDeadline)}</strong></div><div><span>BUYER DECISION</span><strong>{dateLabel(snapshot.buyerDecisionDeadline)}</strong></div><div><span>DISPUTE WINDOW</span><strong>{dateLabel(snapshot.disputeDeadline)}</strong></div><div><span>FALLBACK SUPPLIER</span><strong>{snapshot.fallbackSupplierBps}%</strong></div><div><span>TERMS HASH</span><strong>{shortenAddress(snapshot.termsHash, 12, 8)}</strong></div></div><div className="role-lines-v2"><RoleLine label="BUYER" address={snapshot.buyer} current={role === 'buyer'} /><RoleLine label="SUPPLIER" address={snapshot.supplier} current={role === 'supplier'} /><RoleLine label="ARBITER" address={snapshot.arbiter} current={role === 'arbiter'} /></div><div className="action-footer-v2"><div className="action-footer-head"><RuleLabel>Next permitted action</RuleLabel><span>{nextActionFor(role, snapshot)}</span></div>{role === 'buyer' && (snapshot.status === 0 || snapshot.status === 1) && <ActionButton busy={busy} onClick={() => void send('cancelBeforeFunding')}>Cancel before funding</ActionButton>}{role === 'supplier' && snapshot.status === 0 && !fundingExpired && <ActionButton busy={busy} onClick={() => void send('acceptOrder')}>Accept exact terms</ActionButton>}{role === 'buyer' && snapshot.status === 1 && <ActionButton busy={busy} onClick={() => void send('fund', [], snapshot.orderAmount)}>Fund {money(snapshot.orderAmount)} USDC</ActionButton>}{role === 'supplier' && snapshot.status === 2 && !shipmentExpired && <><Field label="Shipment evidence reference / hash"><input value={evidence} onChange={(e) => setEvidence(e.target.value)} placeholder="Hash or reference text" /></Field><ActionButton busy={busy} disabled={!evidence.trim()} onClick={() => void send('submitShipment', [hashReference(evidence)])}>Submit shipment evidence</ActionButton></>}{role === 'buyer' && snapshot.status === 2 && shipmentExpired && <ActionButton busy={busy} onClick={() => void send('claimShipmentDeadlineRefund')}>Claim shipment deadline refund</ActionButton>}{role === 'buyer' && snapshot.status === 3 && !decisionExpired && <><ActionButton busy={busy} onClick={() => void send('approveShipment')}>Approve shipment / release {money(snapshot.reserveRemaining)}</ActionButton><Field label="Dispute reason commitment"><input value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Hash or reference text" /></Field><ActionButton secondary busy={busy} disabled={!reason.trim()} onClick={() => void send('openDispute', [hashReference(reason)])}>Open dispute</ActionButton></>}{role === 'supplier' && snapshot.status === 3 && decisionExpired && <ActionButton busy={busy} onClick={() => void send('claimBuyerDecisionTimeout')}>Claim buyer decision timeout</ActionButton>}{role === 'arbiter' && snapshot.status === 4 && !disputeExpired && <><Field label="Supplier payout from reserve"><div className="input-unit-v2"><input inputMode="decimal" value={supplierPayout} onChange={(e) => setSupplierPayout(e.target.value)} placeholder="0.0035" /><span>USDC</span></div></Field><ActionButton busy={busy} disabled={!supplierPayout} onClick={() => { try { void send('resolveDispute', [parseAmount(supplierPayout)]); } catch { setError('Enter a valid USDC amount.'); } }}>Resolve dispute</ActionButton></>}{snapshot.status === 4 && disputeExpired && showAction && <ActionButton busy={busy} onClick={() => void send('claimDisputeFallback')}>Claim deterministic fallback</ActionButton>}{role === 'observer' && snapshot.status !== 4 && <p className="action-copy-v2">This wallet is not one of the immutable parties.</p>}{snapshot.status === 5 && <p className="action-copy-v2">Settlement is complete. The contract rejects a second settlement.</p>}{txHash && <div className="form-alert-v2 success"><TxLink hash={txHash}>Transaction confirmed</TxLink></div>}{error && <div className="form-alert-v2 error">{error}</div>}</div><div className="detail-integrity"><span>ACCOUNTING INVARIANT</span><strong>{snapshot.accountingInvariant ? 'TRUE' : 'CHECK REQUIRED'}</strong></div></aside>;
}
function RoleLine({ label, address, current }: { label: string; address: string; current: boolean }) { return <div className={current ? 'role-line-v2 current' : 'role-line-v2'}><span>{label}</span><a href={explorerAddress(address)} target="_blank" rel="noreferrer">{shortenAddress(address)} ↗</a>{current && <b>YOU</b>}</div>; }
function ActionButton({ children, onClick, busy, disabled = false, secondary = false }: { children: React.ReactNode; onClick: () => void; busy: boolean; disabled?: boolean; secondary?: boolean }) { return <button type="button" className={secondary ? 'secondary-button action-button-v2' : 'primary-button action-button-v2'} onClick={onClick} disabled={busy || disabled}>{busy ? 'Waiting for receipt…' : children}</button>; }

function App() {
  const [view, setView] = useState<View>(() => typeof window === 'undefined' ? 'home' : viewFromHash(window.location.hash)); const [account, setAccount] = useState<Address>(); const [walletClient, setWalletClient] = useState<WalletClient>(); const [walletProvider, setWalletProvider] = useState<Eip1193Provider>(); const [orders, setOrders] = useState<EnrichedOrder[]>([]); const [selectedOrder, setSelectedOrder] = useState<Address | undefined>(() => typeof window === 'undefined' ? undefined : orderFromHash(window.location.hash)); const [connectionError, setConnectionError] = useState(''); const ordersRef = useRef<EnrichedOrder[]>([]); const orderScanAccountRef = useRef<string | undefined>(undefined); const orderScanBlockRef = useRef<bigint | undefined>(undefined); const [loadingOrders, setLoadingOrders] = useState(false); const [orderReadState, setOrderReadState] = useState<OrderReadState>('idle'); const [orderReadError, setOrderReadError] = useState('');
 const refreshOrders = useCallback(async (connectedAccount = account) => { if (!connectedAccount) { ordersRef.current = []; orderScanAccountRef.current = undefined; orderScanBlockRef.current = undefined; setOrders([]); setOrderReadState('idle'); setOrderReadError(''); return; } const accountKey = connectedAccount.toLowerCase(); if (orderScanAccountRef.current !== accountKey) { ordersRef.current = []; orderScanBlockRef.current = undefined; orderScanAccountRef.current = accountKey; setOrders([]); } setLoadingOrders(true); setOrderReadState('loading'); setOrderReadError(''); try { const latest = await publicClient.getBlockNumber(); const fromBlock = orderScanBlockRef.current === undefined ? ARC_DEPLOYMENT_BLOCK : orderScanBlockRef.current + 1n; const logs = fromBlock <= latest ? await fetchOrderCreatedLogs(publicClient, { fromBlock, toBlock: latest }) : []; orderScanBlockRef.current = latest; const byOrder = new Map<string, EnrichedOrder>(ordersRef.current.map((log) => [log.order.toLowerCase(), log])); const relatedNew = logs.filter((log) => [log.buyer, log.supplier, log.arbiter].some((address) => address.toLowerCase() === accountKey)); const enriched = await Promise.all(relatedNew.map(async (log) => { try { return { ...log, snapshot: await readOrderSnapshot(publicClient, log.order) }; } catch { return log; } })); enriched.forEach((log) => byOrder.set(log.order.toLowerCase(), log)); const related = Array.from(byOrder.values()).filter((log) => [log.buyer, log.supplier, log.arbiter].some((address) => address.toLowerCase() === accountKey)).sort((left, right) => Number((right.blockNumber ?? 0n) - (left.blockNumber ?? 0n))); ordersRef.current = related; setOrders(related); setOrderReadState('success'); } catch (e) { setOrderReadState('error'); setOrderReadError(errorMessage(e)); } finally { setLoadingOrders(false); } }, [account]);
  const connect = async (provider?: Eip1193Provider) => { setConnectionError(''); try { const result = await connectArcWallet(provider); setWalletProvider(result.provider); setAccount(result.account); setWalletClient(result.walletClient); if (view === 'orders') void refreshOrders(result.account); } catch (e) { setConnectionError(errorMessage(e)); } };
  const syncWallet = async (provider: Eip1193Provider) => { try { const result = await syncArcWallet(provider); if (!result) { setAccount(undefined); setWalletClient(undefined); return; } setAccount(result.account); setWalletClient(result.walletClient); if (view === 'orders') void refreshOrders(result.account); } catch (e) { setAccount(undefined); setWalletClient(undefined); setConnectionError(errorMessage(e)); } };
  useEffect(() => { const provider = walletProvider; if (!provider) return; const handleWalletChange = () => { void syncWallet(provider); }; provider.on?.('accountsChanged', handleWalletChange); provider.on?.('chainChanged', handleWalletChange); return () => { provider.removeListener?.('accountsChanged', handleWalletChange); provider.removeListener?.('chainChanged', handleWalletChange); }; }, [walletProvider, view]);
  useEffect(() => { const handleConnectRequest = () => { void connect(); }; window.addEventListener('cargocommit:connect-wallet', handleConnectRequest); return () => window.removeEventListener('cargocommit:connect-wallet', handleConnectRequest); }, [view]);
  useEffect(() => { const handleRoute = () => { setView(viewFromHash(window.location.hash)); const order = orderFromHash(window.location.hash); if (order) setSelectedOrder(order); }; window.addEventListener('hashchange', handleRoute); window.addEventListener('popstate', handleRoute); return () => { window.removeEventListener('hashchange', handleRoute); window.removeEventListener('popstate', handleRoute); }; }, []);
  useEffect(() => { const nodes = Array.from(document.querySelectorAll<HTMLElement>('[data-reveal]')); if (!nodes.length) return; if (!('IntersectionObserver' in window)) { nodes.forEach((node) => node.classList.add('is-in')); return; } const observer = new IntersectionObserver((entries) => entries.forEach((entry) => { if (entry.isIntersecting) { entry.target.classList.add('is-in'); observer.unobserve(entry.target); } }), { threshold: 0.12, rootMargin: '0px 0px -8% 0px' }); nodes.forEach((node) => observer.observe(node)); return () => observer.disconnect(); }, [view]);
  const selected = orders.find((order) => order.order.toLowerCase() === selectedOrder?.toLowerCase()); const openView = (next: View, order?: Address) => { setView(next); if (order) setSelectedOrder(order); const hash = order && next === 'orders' ? `#orders/${order}` : `#${next === 'home' ? 'overview' : next === 'create' ? 'create-order' : next}`; if (window.location.hash !== hash) window.history.pushState({}, '', hash); window.scrollTo({ top: 0, behavior: 'smooth' }); }; const openAbout = () => { openView('home'); window.setTimeout(() => document.getElementById('arc-stage')?.scrollIntoView({ behavior: 'smooth' }), 0); };
 return <div className="app-shell-v2"><header className="site-header-v2 page-shell"><button className="brand-v2" onClick={() => openView('home')}><span className="brand-mark-v2" aria-hidden="true"><b>S</b><i /></span><span className="brand-wordmark-v2">SELDRA</span></button><nav aria-label="Primary product navigation"><button className={view === 'home' ? 'active' : ''} onClick={() => openView('home')}>OVERVIEW</button><button className={view === 'orders' ? 'active' : ''} onClick={() => openView('orders')}>ORDERS</button><button className={view === 'create' ? 'active' : ''} onClick={() => openView('create')}>CREATE ORDER</button><button className={view === 'proof' ? 'active' : ''} onClick={() => openView('proof')}>PROOF</button></nav><div className="header-right-v2"><NetworkBadge account={account} onConnect={() => void connect()} /></div></header>{connectionError && <div className="global-alert-v2 page-shell"><span>{connectionError}</span><button onClick={() => setConnectionError('')}>Dismiss</button></div>}{view === 'home' && <Landing onView={openView} onConnect={() => void connect()} />}{view === 'proof' && <ProofPage />}{view === 'create' && <CreateOrder account={account} walletClient={walletClient} walletProvider={walletProvider} onCreated={(order) => { setSelectedOrder(order); void refreshOrders(); openView('orders', order); }} />}{view === 'orders' && <><OrdersPage account={account} orders={orders} selected={selectedOrder} onSelect={(order) => openView('orders', order)} onRefresh={() => void refreshOrders()} onConnect={() => void connect()} onCreate={() => openView('create')} loading={loadingOrders} readState={orderReadState} readError={orderReadError} /><section className="page-shell detail-section-v2"><OrderDetail account={account} order={selected} walletClient={walletClient} onRefresh={() => void refreshOrders()} /></section></>}{view !== 'orders' && <footer className="site-footer-v2 page-shell"><div><span>Seldra</span><p>Trade terms that move with the shipment.</p></div><div><button className="footer-anchor" onClick={openAbout}>Why Arc ↗</button><a href={explorerAddress(FACTORY_ADDRESS)} target="_blank" rel="noreferrer">Factory ↗</a><a href="https://github.com/Iniwura/cargocommit" target="_blank" rel="noreferrer">Source ↗</a><a href="https://github.com/Iniwura/cargocommit/blob/master/SECURITY.md" target="_blank" rel="noreferrer">Security ↗</a></div><small>ARC / 5042 / NATIVE USDC</small></footer>}</div>;
}

export default App;
